solution.javascript:
function getStatusCode(scenario) {
    const statusCodes = {
        'success': 200,
        'created': 201,
        'no_content': 204,
        'redirect': 302,
        'permanent_redirect': 301,
        'bad_request': 400,
        'unauthorized': 401,
        'forbidden': 403,
        'not_found': 404,
        'method_not_allowed': 405,
        'conflict': 409,
        'server_error': 500
    };
    return statusCodes[scenario] || 500;
}
